<div class="page-heading admin-heading"><div><span class="eyebrow">Applicant service</span><h1>Support tickets</h1><p>Questions, ownership and response status in one work queue.</p></div></div><div class="filter-tabs"><a class="<?= $status===''?'active':'' ?>" href="<?= url('admin/support') ?>">All <b><?= array_sum(array_column($counts,'total')) ?></b></a><?php foreach($counts as $count):?><a class="<?= $status===$count['status']?'active':'' ?>" href="<?= url('admin/support?status='.$count['status']) ?>"><?= e(ucwords(str_replace('_',' ',$count['status']))) ?> <b><?= e($count['total']) ?></b></a><?php endforeach?></div><section class="card application-table-card"><div class="table-filters"><div class="search-field"><span>⌕</span><input placeholder="Search ticket number, subject or applicant"></div><select><option>All categories</option><option>Admission</option><option>Documents</option><option>Payment</option><option>Technical</option></select></div><div class="table-wrap"><table><thead><tr><th>Ticket</th><th>Applicant</th><th>Category</th><th>Messages</th><th>Owner</th><th>Updated</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($tickets as $ticket):?><tr><td><b><?= e($ticket['subject']) ?></b><small class="completion-small"><?= e($ticket['ticket_number']) ?></small></td><td><div class="person-cell"><span><?= e(strtoupper(substr($ticket['applicant_name'],0,1))) ?></span><div><b><?= e($ticket['applicant_name']) ?></b><small><?= e($ticket['email']) ?></small></div></div></td><td><?= e(ucfirst($ticket['category'])) ?></td><td><?= e($ticket['message_count']) ?></td><td><?= e($ticket['assignee_name']?:'Unassigned') ?></td><td><?= format_date($ticket['updated_at'],true) ?></td><td><span class="status-pill status-<?= e($ticket['status']) ?>"><?= e(ucwords(str_replace('_',' ',$ticket['status']))) ?></span></td><td><a class="row-action" href="<?= url('admin/support/'.$ticket['id']) ?>">→</a></td></tr><?php endforeach?></tbody></table><?php if(!$tickets):?><div class="empty-inline">No support tickets match this view.</div><?php endif?></div></section>
